@KafkaListener(
      topics = "app5541-customer-events",
      groupId = "${spring.kafka.consumer.group-id}",
      containerFactory = "customerListenerContainerFactory",
      concurrency = "3")
  public void consume(@Payload String eventJson) {
    Event<CustomerEventPayload> payload = deserializer.deserialize(eventJson);
    LogUtils.setCorrelationId(payload.getMetadata().getCorrelationId());

    if (StringUtils.hasText(azureAppId) && azureAppId.equals(getRemoteSystem(payload))) {
      log.info(
          "Skip processing event due to event is triggered by the service itself, customerId: {}",
          payload.getPayload().customerId());
      return;
    }
    if (ARCHIVAL_EVENT_TYPE.equals(payload.getMetadata().getType())) {
      log.info(
          "Skip processing event due to customer is archived, eventType: {}, customerId: {}",
          payload.getMetadata().getType(),
          payload.getPayload().customerId());
      return;
    }
    log.info("Consuming customer event, customerId: {}", payload.getPayload().customerId());
    try {
      customerSyncService.syncToCdb(payload.getPayload().customerId(), false);
    } catch (CustomerNotFoundException e) {
      log.error(
          "Failed to sync customer to CDB, customer not found. customerId: {}, message: {}",
          payload.getPayload().customerId(),
          e.getMessage(),
          e);
    }
    log.info("Customer event consumed, customerId: {}", payload.getPayload().customerId());
  }

