private String getRemoteSystem(Event<CustomerEventPayload> payload) {
    return Optional.ofNullable(payload)
        .map(Event::getMetadata)
        .map(Metadata::getAttributes)
        .map(attributes -> attributes.getOrDefault(Constants.REMOTE_SYSTEM_ID, null))
        .orElse(null);
  }

