@KafkaListener(
      topics = "app5541-customer-events",
      groupId = "${spring.kafka.consumer.om-update.group-id}",
      containerFactory = "customerListenerContainerFactory")
  public void consumeToUpdateOM(@Payload String eventJson) {
    Event<CustomerEventPayload> payload = deserializer.deserialize(eventJson);

    LogUtils.setCorrelationId(payload.getMetadata().getCorrelationId());
    String customerId = payload.getPayload().customerId();

    log.info("Consuming customer event to update OM, customerId: {}", customerId);

    if (payload.getMetadata() != null
        && ARCHIVAL_EVENT_TYPE.equals(payload.getMetadata().getType())) {
      log.info(
          "Customer archived event received, skipping OM update. customerId: {}, eventType {}",
          customerId,
          payload.getMetadata().getType());
      return;
    }

    orderManagerService.sendCustomerUpdateEventInOm(CUSTOMER_UPDATE, customerId);

    log.info("Customer event consumed to update OM, customerId: {}", customerId);
  }

