@Retryable(
      includes = {ResourceAccessException.class, CdbConsumerLockedException.class},
      excludes = HttpTimeoutException.class,
      maxRetriesString = "${rest-client-config.retry.max-attempts}",
      delayString = "${rest-client-config.retry.cdb-delay}")
  public ConsumerResponse createOrUpdateConsumer(CreateOrUpdateRequest createOrUpdateRequest) {
    CdbResponse response;
    try {
      response =
          client
              .post()
              .uri("/consumer")
              .body(createOrUpdateRequest)
              .retrieve()
              .toEntity(CdbResponse.class)
              .getBody();
    } catch (ResourceAccessException exception) {
      throw exception;
    } catch (HttpClientErrorException.BadRequest e) {
      throw toBadRequestException(e);
    } catch (RestClientException e) {
      throw new CdbClientException(format("Failed to update or create customer in cdb"), e);
    }

    if (response == null || response.responseDetails() == null) {
      throw new CdbClientException(
          "Failed to update or create customer in cdb, unexpected empty response");
    }

    return response.responseDetails();
  }

