private CdbClientException toBadRequestException(HttpClientErrorException.BadRequest e) {
    String description = getErrorDescription(e.getResponseBodyAsString());
    if (description.contains("LOCKED") || description.contains("MODIFIED")) {
      log.warn("CDB consumer record locked or modified, retrying. description: {}", description);
      return new CdbConsumerLockedException(
          "CDB consumer record locked or modified: " + description, e);
    }
    log.warn("CDB rejected customer data. description: {}", description);
    return new CdbDataRejectedException(
        "Failed to update or create customer in cdb, rejected by cdb: " + description, e);
  }

