private String getErrorDescription(String body) {
    if (!StringUtils.hasText(body)) {
      return "no response body";
    }
    try {
      JsonNode root = jsonMapper.readTree(body);
      List<String> descriptions = new ArrayList<>();
      for (JsonNode error : root.path("responseDetails").path("nounFailure").path("errorMessage")) {
        String description = error.path("description").asString("");
        if (StringUtils.hasText(description)) {
          descriptions.add(description);
        }
      }
      if (!descriptions.isEmpty()) {
        return String.join("; ", descriptions);
      }
      String errorMessage = root.path("errorMessage").asString("");
      return StringUtils.hasText(errorMessage) ? errorMessage : body;
    } catch (JacksonException _) {
      return body;
    }
  }

