public List<CreateOrUpdateAddress> toList(Actor actor) {
    if (actor == null || CollectionUtils.isEmpty(actor.addresses())) {
      return null;
    }

    Set<ComparableAddress> processedAddresses = new HashSet<>();
    return actor.addresses().stream()
        .filter(
            address ->
                !address.previous() && processedAddresses.add(new ComparableAddress(address)))
        .map(address -> toAddress(address, getAddressType(actor)))
        .filter(Objects::nonNull)
        .toList();
  }

