    if (!StringUtils.hasText(individual.cdbId()) && StringUtils.hasText(individual.volvoId())) {
      alternativeConsumerIds.add(buildAlternativeConsumerId(VOLVO_ID_TYPE, individual.volvoId()));
    }

    return alternativeConsumerIds;
