private String getId(String idType, ConsumerResponse cdbResponse) {
    List<ConsumerResponse.Id> consumerIds =
        Optional.ofNullable(cdbResponse)
            .map(ConsumerResponse::consumerId)
            .map(ConsumerResponse.ConsumerId::id)
            .orElse(List.of());
    return consumerIds.stream()
        .filter(id -> idType.equalsIgnoreCase(id.type()))
        .findFirst()
        .map(ConsumerResponse.Id::value)
        .orElse(null);
  }

