private Map<String, Object> getCustomerConsumerSettings() {
    Map<String, Object> consumerSettings = new HashMap<>();
    consumerSettings.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, kafkaSettings.bootstrapServers());
    consumerSettings.put(
        ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, kafkaSettings.consumer().autoOffsetReset());

    consumerSettings.put(
        ConsumerConfig.RECONNECT_BACKOFF_MS_CONFIG, kafkaSettings.reconnectBackoff());
    consumerSettings.put(
        ConsumerConfig.RECONNECT_BACKOFF_MAX_MS_CONFIG, kafkaSettings.reconnectBackoffMax());

    consumerSettings.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);
    consumerSettings.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);

    consumerSettings.put(
        ErrorHandlingDeserializer.KEY_DESERIALIZER_CLASS, StringDeserializer.class);
