    consumerSettings.put(ConsumerConfig.MAX_POLL_RECORDS_CONFIG, kafkaSettings.maxPollRecords());
    consumerSettings.put(
        ConsumerConfig.MAX_POLL_INTERVAL_MS_CONFIG, kafkaSettings.maxPollIntervalMs());

    setSecuritySettings(consumerSettings, kafkaSettings);
    return consumerSettings;
  }

