@Override
  public void accept(ConsumerRecord<?, ?> rec, Exception exception) {
    String key = getKey(rec);
    String payload = getPayload(rec);

    CdbDataRejectedException dataRejected = findDataRejectedCause(exception);
    if (dataRejected != null) {
      logger.warn(
          "Customer event not retried, data rejected by CDB. key: {}, payload: {}, message: {}",
          key,
          payload,
          dataRejected.getMessage());
      return;
    }

    String stackTrace = extractStackTrace(exception);

    logger.error(
        "Max attempt reached for customer event. key: {}, payload: {}, stackTrace: {}",
        key,
        payload,
        stackTrace);
  }

