private CdbSyncResult.Actor syncToCdb(
      Customer customer,
      CorporateEntity corporateEntity,
      String relatedCdbId,
      VehicleRelationRequest vehicleRelationRequest,
      boolean create) {
    if (shouldSkip(corporateEntity, create)) {
      log.info(
          "Skipping corporate entity sync to CDB. customerId: {}, corporateEntityId: {}, cdbId: {}",
          customer.customerId(),
          corporateEntity.id(),
          corporateEntity.cdbId());
      return toUnchangedResponse(corporateEntity);
    }
    log.info(
        "Syncing corporate entity to CDB. customerId: {}, corporateEntityId: {}, currentCdbId: {}",
        customer.customerId(),
        corporateEntity.id(),
        corporateEntity.cdbId());

    CreateOrUpdateRequest cdbRequest =
        createOrUpdateRequestMapper.fromActor(
            customer, corporateEntity, relatedCdbId, vehicleRelationRequest);
    ConsumerResponse cdbResponse = cdbClient.createOrUpdateConsumer(cdbRequest);
    String cdbId = createOrUpdateConsumerResponseMapper.getCdbId(cdbResponse);
    String tcId = createOrUpdateConsumerResponseMapper.getTcId(cdbResponse);
    log.info(
        "Corporate entity synced to CDB. customerId: {}, corporateEntityId: {}, cdbId: {}, tcId: {}",
        customer.customerId(),
        corporateEntity.id(),
        cdbId,
        tcId);
    if (isUnchanged(cdbId, corporateEntity.cdbId())
        && isUnchanged(tcId, corporateEntity.cdbTcId())) {
      return toUnchangedResponse(corporateEntity);
    }
    return new CdbSyncResult.Actor(corporateEntity.id(), cdbId, tcId, true);
  }

