public CdbSyncResult syncToCdb(
      String customerId, VehicleRelationRequest vehicleRelation, boolean create) {
    Customer customer = customerService.getCustomer(customerId);

    List<CdbSyncResult.Actor> individuals =
        individualSyncService.syncToCdb(customer, vehicleRelation, create);
    String signatoryCdbId = getSignatoryCdbId(customer, individuals);
    List<CdbSyncResult.Actor> corporateEntities =
