private String getSignatoryCdbId(Customer customer, List<CdbSyncResult.Actor> individuals) {
    Individual signatory =
        customer.individuals().stream()
            .filter(individual -> individual.roles().contains(Role.SIGNATORY))
            .findFirst()
            .orElse(null);
    if (signatory == null) {
      return null;
    }
    return individuals.stream()
        .filter(individual -> Objects.equals(signatory.id(), individual.id()))
        .findFirst()
        .map(CdbSyncResult.Actor::cdbId)
        .orElse(signatory.cdbId());
  }

