private CdbSyncResult.Actor syncToCdb(
      Customer customer,
      Individual individual,
      VehicleRelationRequest vehicleRelationRequest,
      boolean create) {
    if (shouldSkip(customer, individual, create)) {
      log.info(
          "Skipping individual sync to CDB. customerId: {}, individualId: {}, cdbId: {}",
          customer.customerId(),
          individual.id(),
          individual.cdbId());
      return toUnchangedResponse(individual);
    }
    log.info(
        "Syncing individual to CDB. customerId: {}, individualId: {}, currentCdbId: {}",
        customer.customerId(),
        individual.id(),
        individual.cdbId());

    CreateOrUpdateRequest cdbRequest =
        createOrUpdateRequestMapper.fromActor(customer, individual, vehicleRelationRequest);
    ConsumerResponse cdbResponse = cdbClient.createOrUpdateConsumer(cdbRequest);
    String cdbId = createOrUpdateConsumerResponseMapper.getCdbId(cdbResponse);
    String tcId = createOrUpdateConsumerResponseMapper.getTcId(cdbResponse);
    log.info(
        "Individual synced to CDB. customerId: {}, individualId: {}, cdbId: {}, tcId: {}",
        customer.customerId(),
        individual.id(),
        cdbId,
        tcId);
    if (isUnchanged(cdbId, individual.cdbId()) && isUnchanged(tcId, individual.cdbTcId())) {
      return toUnchangedResponse(individual);
    }
    return new CdbSyncResult.Actor(individual.id(), cdbId, tcId, true);
  }

