@Retryable(
      includes = ResourceAccessException.class,
      maxRetriesString = "${rest-client-config.retry.max-attempts}",
      delayString = "${rest-client-config.retry.max-delay}")
  public void sendCustomerUpdateEventInOm(OMCustomerUpdateEventRequest request, String customerId) {
    try {
      client
          .post()
          .uri("/internal/ordermanager/v1/orders/customer-update-event/{customerId}", customerId)
          .body(request)
          .retrieve()
          .toBodilessEntity();
    } catch (ResourceAccessException e) {
      // Needed to make the retryable annotation work
      throw e;
    } catch (HttpClientErrorException.NotFound e) {
      // We can safely ignore 404, this will happen before any orders are created for the customer
      log.info(
          "Customer not found or no orders assigned to customer, customerId: {}", customerId, e);
    } catch (HttpClientErrorException.Conflict e) {
      // We can ignore 409, this is due to a problem in OM where they actually produce the event but
      // fail to persist in their database and retrying would just produce duplicate events.
      log.info(
          "Conflict response from OM when sending customer event, customerId: {}", customerId, e);
    } catch (RestClientException e) {
      throw new OrderManagerApiException(
          "Unexpected error from OrderManager (sendCustomerUpdateEventInOm). customerId: "
              + customerId,
          e);
    }
  }

