@Test
  void getConsumerByVolvoIdWhenValuesAreSetShouldSucceed() {
    var volvoId = Instancio.create(String.class);
    var consumer = Instancio.create(CdbConsumerByVolvoId.class);
    when(cdbClient.getCdbConsumerByVolvoId(volvoId)).thenReturn(consumer);

    CdbConsumerData result = service.getConsumerByVolvoId(volvoId);

    assertEquals(consumer.consumerInfo().consumerId(), result.consumerId());
    assertEquals(consumer.consumerInfo().globalConsumerId(), result.globalConsumerId());
    assertEquals(consumer.alternativeConsumerIds().size(), result.alternateConsumerList().size());
    IntStream.range(0, result.alternateConsumerList().size())
        .forEach(
            index -> {
              assertEquals(
                  consumer.alternativeConsumerIds().get(index).type(),
                  result.alternateConsumerList().get(index).type());
              assertEquals(
                  consumer.alternativeConsumerIds().get(index).value(),
