@Test
  void createOrUpdateConsumerShouldRetryOnLockedButNotOnDataRejected() throws Exception {
    Retryable retryable =
        CdbClient.class
            .getMethod("createOrUpdateConsumer", CreateOrUpdateRequest.class)
            .getAnnotation(Retryable.class);

    assertTrue(Arrays.asList(retryable.includes()).contains(CdbConsumerLockedException.class));
    assertTrue(Arrays.asList(retryable.includes()).contains(ResourceAccessException.class));
    assertFalse(Arrays.asList(retryable.includes()).contains(CdbDataRejectedException.class));
