@Test
  void fromActorShouldSucceed() {
    var customer = Instancio.create(Customer.class);
    var actor = Instancio.create(Individual.class);
    var relatedCdbId = "relatedCdbId";
    var vehicleRelationInput = Instancio.create(VehicleRelationRequest.class);

    var consumerInfo = Instancio.create(CreateOrUpdateConsumerInfo.class);
    var alternativeConsumerId = Instancio.createList(CreateOrUpdateAlternativeConsumerId.class);
    var consumerRelation = Instancio.createList(CreateOrUpdateConsumerRelation.class);
    var person = Instancio.create(CreateOrUpdatePerson.class);
    var organization = Instancio.create(CreateOrUpdateOrganization.class);
    var address = Instancio.createList(CreateOrUpdateAddress.class);
    var contactDetails = Instancio.createList(CreateOrUpdateContactDetails.class);
    var emailAddress = Instancio.createList(CreateOrUpdateEmailAddress.class);
    var vehicleRelation = Instancio.createList(CreateOrUpdateVehicleRelation.class);

    when(consumerInfoMapper.fromActor(customer, actor)).thenReturn(consumerInfo);
    when(alternativeConsumerIdMapper.fromActor(actor)).thenReturn(alternativeConsumerId);
    when(consumerRelationMapper.toList(customer, relatedCdbId)).thenReturn(consumerRelation);
    when(personMapper.fromActor(actor)).thenReturn(person);
    when(organizationMapper.fromActor(actor)).thenReturn(organization);
    when(addressMapper.toList(actor)).thenReturn(address);
    when(contactDetailsMapper.toList(actor)).thenReturn(contactDetails);
    when(emailAddressMapper.toList(actor)).thenReturn(emailAddress);
    when(vehicleRelationsMapper.fromActor(
            vehicleRelationInput.vin(), vehicleRelationInput.handoverDate(), actor))
        .thenReturn(vehicleRelation);

    var result =
        createOrUpdateConsumerMapper.fromActor(customer, actor, relatedCdbId, vehicleRelationInput);

    assertEquals(consumerInfo, result.getConsumerInfo());
    assertEquals(alternativeConsumerId, result.getAlternativeConsumerId());
    assertEquals(consumerRelation, result.getConsumerRelation());
    assertEquals(person, result.getPerson());
    assertEquals(organization, result.getOrganization());
    assertEquals(address, result.getAddress());
    assertEquals(contactDetails, result.getContactDetails());
    assertEquals(emailAddress, result.getEmailAddress());
    assertEquals(vehicleRelation, result.getVehicleRelation());
  }

