private RestClient.ResponseSpec setupPostPutClientMock(OMCustomerUpdateEventRequest request) {
    var spec = mock(RestClient.RequestBodyUriSpec.class);
    var responseSpec = mock(RestClient.ResponseSpec.class);
    when(spec.uri(
            "/internal/ordermanager/v1/orders/customer-update-event/{customerId}", customerId))
        .thenReturn(spec);
    when(spec.contentType(
            MediaType.valueOf(
                "application/vnd.volvocars.api.ordermanager.customerupdatedeventrequest.v1+json")))
        .thenReturn(spec);
    when(restClient.post()).thenReturn(spec);
    when(restClient.put()).thenReturn(spec);
    when(spec.body(request)).thenReturn(spec);
    when(spec.retrieve()).thenReturn(responseSpec);
    return responseSpec;
  }

